<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">   input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: Type[Any] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> None</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
